// ============================================================
// WF-A STEP 1 — Validate & prepare content for all platforms
// ============================================================
// Expected input JSON:
// {
//   "brand": "longislandconvenience",
//   "content_type": "blog | product | video | image | promotion",
//   "text": "Short caption (max 280 chars)",
//   "text_long": "Full post text (1000 chars max)",
//   "image_url": "https://...",
//   "video_url": "https://... (optional)",
//   "link_url": "https://longislandconvenience.com/blog/...",
//   "hashtags": ["LongIsland", "Plainview", "NassauCounty"],
//   "platforms": ["facebook","instagram","pinterest","twitter","linkedin"]
// }

const body = $input.first().json.body;

// Brand configs — fill in your real IDs below
const BRAND_CONFIGS = {
  longislandconvenience: {
    fb_page_id:    'FILL_YOUR_FB_PAGE_ID',
    ig_account_id: 'FILL_YOUR_IG_ACCOUNT_ID',
    pinterest_board_id: 'FILL_YOUR_PINTEREST_BOARD_ID',
    linkedin_org_id: 'FILL_YOUR_LINKEDIN_ORG_ID',
    default_hashtags: ['LongIsland','PlainviewNY','NassauCounty','ShopLocal','LongIslandLife'],
  },
  longislandcards: {
    fb_page_id:    'FILL_YOUR_FB_PAGE_ID_CARDS',
    ig_account_id: 'FILL_YOUR_IG_ACCOUNT_ID_CARDS',
    pinterest_board_id: null,
    linkedin_org_id: null,
    default_hashtags: ['SportsCards','LongIsland','PlainviewNY','PSAGraded','PokemonCards'],
  },
  ligiftbasket: {
    fb_page_id:    'FILL_YOUR_FB_PAGE_ID_GIFT',
    ig_account_id: 'FILL_YOUR_IG_ACCOUNT_ID_GIFT',
    pinterest_board_id: 'FILL_YOUR_PINTEREST_BOARD_ID_GIFT',
    linkedin_org_id: null,
    default_hashtags: ['GiftBasket','LongIsland','PlainviewNY','GiftIdeas','CustomGifts'],
  },
  longislandballoonsdecor: {
    fb_page_id:    'FILL_YOUR_FB_PAGE_ID_BALLOONS',
    ig_account_id: 'FILL_YOUR_IG_ACCOUNT_ID_BALLOONS',
    pinterest_board_id: 'FILL_YOUR_PINTEREST_BOARD_ID_BALLOONS',
    linkedin_org_id: null,
    default_hashtags: ['BalloonDecor','LongIsland','PlainviewNY','BalloonArch','EventDecor'],
  },
  longislandprintandmail: {
    fb_page_id:    'FILL_YOUR_FB_PAGE_ID_PRINT',
    ig_account_id: 'FILL_YOUR_IG_ACCOUNT_ID_PRINT',
    pinterest_board_id: null,
    linkedin_org_id: 'FILL_YOUR_LINKEDIN_ORG_ID_PRINT',
    default_hashtags: ['PrintShop','LongIsland','PlainviewNY','BusinessCards','SameDay'],
  },
  jhdadvisor: {
    fb_page_id:    'FILL_YOUR_FB_PAGE_ID_JHD',
    ig_account_id: 'FILL_YOUR_IG_ACCOUNT_ID_JHD',
    pinterest_board_id: null,
    linkedin_org_id: 'FILL_YOUR_LINKEDIN_ORG_ID_JHD',
    default_hashtags: ['AIAgency','DigitalMarketing','LongIsland','Automation','SEO'],
  },
};

// Merge hashtags
const brandCfg = BRAND_CONFIGS[body.brand] || BRAND_CONFIGS.longislandconvenience;
const allTags = [...new Set([...(body.hashtags || []), ...brandCfg.default_hashtags])];
const hashtagString = allTags.map(t => `#${t.replace(/^#/,'')}`).join(' ');

// Platform-specific text limits
const LIMITS = { facebook: 63206, instagram: 2200, pinterest: 500, twitter: 280, linkedin: 3000 };

function truncate(text, max) {
  if (!text) return '';
  return text.length <= max ? text : text.slice(0, max - 3) + '...';
}

const baseText = body.text_long || body.text || '';
const shortText = body.text || baseText.slice(0, 280);

// Prepare platform payloads
const prepared = {
  brand: body.brand,
  brand_config: brandCfg,
  image_url: body.image_url || null,
  video_url: body.video_url || null,
  link_url: body.link_url || null,
  content_type: body.content_type || 'post',
  platforms: body.platforms || ['facebook','instagram'],

  facebook_text: truncate(`${baseText}\n\n${hashtagString}${body.link_url ? '\n\n' + body.link_url : ''}`, 63206),
  instagram_caption: truncate(`${baseText}\n\n${hashtagString}`, 2200),
  pinterest_description: truncate(baseText, 500),
  pinterest_title: truncate(shortText, 100),
  twitter_text: truncate(`${shortText} ${allTags.slice(0,3).map(t=>'#'+t).join(' ')}${body.link_url ? ' ' + body.link_url : ''}`, 280),
  linkedin_text: truncate(`${baseText}\n\n${hashtagString}`, 3000),
};

return [{ json: prepared }];

